Object.entries(overlayTranslations).forEach(([lang, values]) => {
  translations[lang] = { ...(translations[lang] || {}), ...values };
});

function interpolate(value, vars = {}) {
  if (typeof value !== 'string') return value;
  return value.replace(/\{(\w+)\}/g, (_, key) => (vars[key] ?? `{${key}}`));
}

const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState('it');
  const t = (key, vars) => interpolate(translations[language]?.[key] ?? translations.it[key] ?? key, vars);
  return (
    <LanguageContext.Provider value={{ language, setLanguage, languages, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used within LanguageProvider');
  return context;
}
